    function isUsableTextarea(value){ return value instanceof HTMLTextAreaElement && !value.disabled && !value.readOnly && value.isConnected && !value.closest('.qmx-genetics-editor'); }
    function visibleTextareaCandidates(){ return Array.from(document.querySelectorAll('textarea')).filter((textarea)=>isUsableTextarea(textarea) && (textarea.offsetParent!==null || textarea.getClientRects().length>0)); }
    function resolveQuestionTextarea(context={}){const direct=[context.textarea,context.targetTextarea,context.activeTextarea,context.field,lastExternalTextarea];try{direct.push(window.QmxDiagramLauncher?.getActiveTextarea?.());}catch(error){}for(const textarea of direct){if(isUsableTextarea(textarea))return textarea;}const active=document.activeElement;if(isUsableTextarea(active))return active;const candidates=visibleTextareaCandidates();const scored=candidates.map((textarea)=>{const marker=`${textarea.name||''} ${textarea.id||''} ${textarea.dataset?.field||''} ${textarea.getAttribute('aria-label')||''}`.toLowerCase();let score=0;if(/question|stem|prompt|creative|cq|part/.test(marker))score+=8;if(/answer|solution/.test(marker))score-=2;if(textarea.value?.includes('[[qmx-diagram:'))score+=1;return{textarea,score};}).sort((a,b)=>b.score-a.score);return scored[0]?.textarea||null;}
    function dispatchTextareaUpdate(textarea){ textarea.dispatchEvent(new InputEvent('input',{bubbles:true,inputType:'insertText',data:null})); textarea.dispatchEvent(new Event('change',{bubbles:true})); textarea.dispatchEvent(new Event('keyup',{bubbles:true})); }
    function writeTokenToTextarea(textarea,token){if(!isUsableTextarea(textarea))return null;let start=Number.isInteger(textarea.selectionStart)?textarea.selectionStart:textarea.value.length;let end=Number.isInteger(textarea.selectionEnd)?textarea.selectionEnd:start;if(state.context?.replaceRange && Number.isInteger(state.context.replaceRange.start) && Number.isInteger(state.context.replaceRange.end)){start=Math.max(0,Math.min(textarea.value.length,state.context.replaceRange.start));end=Math.max(start,Math.min(textarea.value.length,state.context.replaceRange.end));}if(typeof textarea.setRangeText==='function')textarea.setRangeText(token,start,end,'end');else{textarea.value=textarea.value.slice(0,start)+token+textarea.value.slice(end);textarea.selectionStart=textarea.selectionEnd=start+token.length;}state.context.replaceRange={start,end:start+token.length};dispatchTextareaUpdate(textarea);return textarea;}
    function createDocument(){ return { version:34,id:uid('genetics-diagram'),mode:'genetics-diagram',title:'Genetics / DNA & Inheritance Diagram',width:1180,height:720,background:'#ffffff',gridSize:20,geneticsShowGrid:false,geneticsShowLabels:true,geneticsShowStructures:true,geneticsShowDetails:true,geneticsShowSequences:true,snap:true,objects:[] }; }
