    function organStyle(kind){ return ({'homologous-pair':['#ede9fe','#7c3aed'],chromatid:['#ddd6fe','#6d28d9'],centromere:['#fef3c7','#d97706'],'gene-segment':['#dcfce7','#16a34a'],nucleotide:['#e0f2fe','#0284c7'],'base-pair':['#fee2e2','#dc2626'],'replication-fork':['#dbeafe','#2563eb'],mrna:['#ccfbf1','#0f766e'],ribosome:['#fce7f3','#be185d'],'protein-chain':['#fef3c7','#a16207'],'punnett-square':['#f8fafc','#334155'],'cell-nucleus':['#f1f5f9','#475569'],spindle:['#e0e7ff','#4f46e5'],'crossing-over':['#fae8ff','#a21caf'],allele:['#ecfccb','#4d7c0f']})[kind]||['#f8fafc','#475569']; }
    function defaultSize(kind){ return ({'homologous-pair':[260,330],chromatid:[110,290],centromere:[120,70],'gene-segment':[240,80],nucleotide:[165,125],'base-pair':[200,95],'replication-fork':[380,420],mrna:[260,115],ribosome:[220,170],'protein-chain':[260,115],'punnett-square':[460,460],'cell-nucleus':[230,230],spindle:[280,220],'crossing-over':[280,360],allele:[160,70]})[kind]||[130,95]; }
    function makeOrgan(kind='gene-segment',overrides={}){ const [fill,stroke]=organStyle(kind),[width,height]=defaultSize(kind);return{id:uid('genetics-component'),type:'genetics-component',kind,x:440,y:260,width,height,label:kind.replace(/-/g,' '),fill,stroke,textColor:'#1e293b',lineWidth:2.5,rotation:0,detailCount:kind==='punnett-square'?2:6,sequence:kind==='gene-segment'?'ATG CCA TAA':kind==='mrna'?'AUG CCA UAA':'',parentA:'A,a',parentB:'A,a',...overrides}; }
    function makeLabel(targetId='',targetPort='e',overrides={}){ return{id:uid('genetics-label'),type:'genetics-label',targetId,targetPort,x:830,y:150,width:220,height:50,text:'Genetic element',fill:'#ffffff',stroke:'#334155',textColor:'#0f172a',lineWidth:2,...overrides}; }
