    function makeArrow(overrides={}){ return{id:uid('genetics-arrow'),type:'genetics-arrow',x1:340,y1:610,x2:670,y2:610,label:'genetic process',stroke:'#0f766e',textColor:'#115e59',lineWidth:3,dashed:false,...overrides}; }
